PRAGMA foreign_keys = ON;
DROP TABLE IF EXISTS pagamento;
CREATE TABLE IF NOT EXISTS usuario (id INTEGER PRIMARY KEY, nome TEXT NOT NULL, email TEXT NOT NULL UNIQUE, senha TEXT NOT NULL DEFAULT '123456');
CREATE TABLE IF NOT EXISTS produto (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER NOT NULL, nome TEXT NOT NULL, categoria TEXT NOT NULL DEFAULT 'Hortaliças', descricao TEXT, foto TEXT, preco REAL NOT NULL, ativo INTEGER NOT NULL DEFAULT 1, data_cadastro TEXT NOT NULL, FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE IF NOT EXISTS lote (id INTEGER PRIMARY KEY AUTOINCREMENT, produto_id INTEGER NOT NULL, origem TEXT, data_producao TEXT NOT NULL, data_validade TEXT NOT NULL, quantidade_total INTEGER NOT NULL, quantidade_disponivel INTEGER NOT NULL, quantidade_reservada INTEGER NOT NULL DEFAULT 0, quantidade_vendida INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(produto_id) REFERENCES produto(id));
CREATE TABLE IF NOT EXISTS local_retirada (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER NOT NULL, nome TEXT NOT NULL, endereco TEXT NOT NULL, FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE IF NOT EXISTS horario_retirada (id INTEGER PRIMARY KEY AUTOINCREMENT, local_retirada_id INTEGER NOT NULL, dia_semana INTEGER NOT NULL, hora_inicio TEXT NOT NULL, hora_fim TEXT NOT NULL, capacidade_atendimento INTEGER NOT NULL CHECK (capacidade_atendimento > 0), FOREIGN KEY(local_retirada_id) REFERENCES local_retirada(id));
CREATE TABLE IF NOT EXISTS reserva_atendimento (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL, comprador_id INTEGER NOT NULL, horario_retirada_id INTEGER NOT NULL, data_retirada TEXT NOT NULL, status TEXT NOT NULL, FOREIGN KEY(horario_retirada_id) REFERENCES horario_retirada(id));
CREATE UNIQUE INDEX IF NOT EXISTS ux_reserva_atendimento_ativa ON reserva_atendimento(pedido_id) WHERE status = 'ATIVA';
CREATE TABLE IF NOT EXISTS pedido (id INTEGER PRIMARY KEY AUTOINCREMENT, comprador_id INTEGER NOT NULL, status TEXT NOT NULL, valor_total REAL NOT NULL, data_pedido TEXT NOT NULL, FOREIGN KEY(comprador_id) REFERENCES usuario(id));
CREATE TABLE IF NOT EXISTS item_pedido (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL, produto_id INTEGER NOT NULL, quantidade INTEGER NOT NULL, preco_unitario REAL NOT NULL, subtotal REAL NOT NULL, FOREIGN KEY(pedido_id) REFERENCES pedido(id), FOREIGN KEY(produto_id) REFERENCES produto(id));
CREATE TABLE IF NOT EXISTS reserva_estoque (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL, lote_id INTEGER NOT NULL, quantidade INTEGER NOT NULL, FOREIGN KEY(pedido_id) REFERENCES pedido(id), FOREIGN KEY(lote_id) REFERENCES lote(id));
CREATE TABLE IF NOT EXISTS fatura (id INTEGER PRIMARY KEY AUTOINCREMENT, pedido_id INTEGER NOT NULL, valor REAL NOT NULL, status TEXT NOT NULL, FOREIGN KEY(pedido_id) REFERENCES pedido(id));
